"""Retain exact local messages and publish source-reviewed daily status."""
import hashlib,json,shutil
from pathlib import Path
from datetime import datetime,timezone
ROOT=Path(__file__).resolve().parents[1]
save=lambda p,v:p.write_text(json.dumps(v,indent=2,ensure_ascii=False)+'\n')

def main():
    review=json.loads((ROOT/'verification/firmware-initial-GPU-review.json').read_text());out=Path(review['directory'])
    local=Path(json.loads((ROOT/'verification/easy-firmware-initial-GPU-scope-pointer.json').read_text())['directory'])
    run=json.loads((local/'protocol.json').read_text());item=run['results'][0]
    assert run['status']=='completed_pending_coordinator_review' and item['words']==89 and not item['quality_flags']
    answer=item['answer']
    assert all(s in answer for s in ['228 bytes','433-step','60,000-byte','cannot boot yet','discovery only'])
    result=dict(status='local_initial_GPU_and_next_CPU_scope_source_review_accepted',directory=str(local),words=item['words'],seconds=item['seconds'],interface='LM Studio SDK with installed evidence tool; native Chat not newly tested',tool_calls=1,roles=['Analyst','Restorer','Reviewer'],same_model_weights=True,independent_model_verification=False,new_weight_training=False,review_basis='Compared answer manually against independent native/C initial GPU proof and actual CPU-after-GPU listing. Initial wait C, 228-byte copy/jump/five-counter wait, 433-step discovery-only scope, separate supplied stub and remaining full boot are stated correctly.',unproven='One diagnostic source question does not establish broad reliability, completed decompilation, trained game weights, or future 256GB performance.')
    save(local/'coordinator-review.json',result);save(out/'local-review.json',result)
    with (out/'who-prompts-and-responses.txt').open('a') as f:f.write('\nLOCAL ROLE INFERENCE\n'+(local/'prompts-and-responses.txt').read_text()+'\nCOORDINATOR REVIEW\n'+json.dumps(result,indent=2)+'\n')
    proof=json.loads((ROOT/'verification/firmware-initial-GPU-live-checks.json').read_text());review['proof']=proof;review['local_review']=result
    files=[ROOT/'scripts/record_firmware_initial_GPU_local_review.py',ROOT/'scripts/check_biwn_firmware_initial_GPU_live.py',ROOT/'verification/firmware-initial-GPU-live-checks.json',local/'protocol.json',local/'prompts-and-responses.txt',local/'coordinator-review.json']
    for i,p in enumerate(files):
        target=out/f'local-{i:02d}-{p.name}';shutil.copy2(p,target);review['manifest'].append(dict(source=str(p),snapshot=str(target),sha256=hashlib.sha256(target.read_bytes()).hexdigest()))
    save(out/'review.json',review);save(ROOT/'verification/firmware-initial-GPU-review.json',review)
    now=datetime.now(timezone.utc).isoformat()
    native=ROOT/'verification/firmware-relocation-review/20261015T011820.772829Z/native-chat-export.md'
    summary=review['evidence']['plain_language_summary']
    (ROOT/'START HERE.txt').write_text(f'''LOCAL AI LAB — CURRENT START\nUpdated {now}\n\nEASY LOCAL CHAT\nOpen LM Studio. Use advertising-scholar with Game Assistant for BIWN, or Advertising Researcher/Educator for advertising. Keep local-ai-lab enabled for evidence and previews. The everyday model remains 27B/6bit, 32,768 context, one worker.\nTry: What changed in the initial GPU wait, what does the CPU do next, and can the full rebuilt game boot yet?\n\nGAME PROGRESS\n{summary}\nThe initial wait matched all 8 source instructions over 259,413 executed instructions. The resumed renderer still matched 1,317 instruction versions and 104,628 executed instructions, with 1,352 standalone checkpoints. Original GPU instruction execution on these C paths: zero. Main CPU, shared peripheral models, initial GPU pipeline tail and explicit event schedule remain providers.\n\nLOCAL OUTPUT TEST\nThe everyday model used one evidence lookup and produced an accurate 89-word Analyst/Restorer/Reviewer explanation in {item['seconds']:.2f} seconds through the SDK. Same weights for every role. This run did not use the native Chat window or change weights.\n{out/'who-prompts-and-responses.txt'}\nEarlier visible native Chat prompts/tools/responses:\n{native}\n\nADVERTISING\nAdvertising Analysis Pilot v2 is trained, exported and loadable, but remains experimental after semantic, rubric and tool-format failures. The everyday model stays the default.\n{ROOT/'verification/advertising-analysis-v2-review.json'}\n\nSOURCE AUDIT\n{out/'review.json'}\n\nNEXT\nReconstruct the next 15 CPU instructions, advance source video interrupts, then trace disc header/loading and natural game dispatch. Global timing and full playability remain unfinished.\n''')
    current=ROOT/'CURRENT DECOMPILATION.txt';previous=current.read_text();current.write_text(f'INITIAL GPU WAIT RECONSTRUCTED; NEXT CPU WAIT DISCOVERED\n{now}\n\n{summary}\n\nInitial wait: 8/8 source instructions, 259,413 executed instructions, 194,561 outer blocks. The block count is an observation quantum, not a physical duration. Logical GPU 4,396 bytes, private 2MB RAM, CPU state, available peripheral snapshots, PC trace and instruction counts match the fixed independent native run. Twenty initial GPU pipeline bytes are excluded. Live private Blitter state is not compared here; the standalone renderer proof checks it separately.\n\nLocal output: 89 words/{item["seconds"]:.2f} seconds, one evidence tool call, normal EOS; coordinator source review accepted the scope. Roles share one model. No new weight training or native UI test.\n\nAUDIT\n{out}\n\nNEXT\n{review["evidence"]["next_GPU_CPU_dependency"]["next_action"]}\n\nEARLIER CHECKPOINTS\n'+previous)
    (ROOT/'CURRENT LOCAL INFERENCE.txt').write_text(f'''CURRENT LOCAL INFERENCE\nUpdated {now}\n\nEveryday advertising-scholar: 27B/6bit, 32,768 context, one worker. Existing Game Assistant and Advertising presets/tools remain configured. Daily model and weights unchanged.\n\nNEW OUTPUT TEST\nOne natural source question, one project_evidence lookup, 89-word Analyst/Restorer/Reviewer answer in {item['seconds']:.2f} seconds through LM Studio SDK. Normal EOS, no quality flags; coordinator review accepted C initial GPU wait, next CPU copy/jump/video-counter wait, discovery-only scope and unfinished full boot. Same weights play all roles; this is a bounded diagnostic.\n{out/'who-prompts-and-responses.txt'}\n{out/'local-review.json'}\n\nSOURCE PROGRESS\n{summary}\n{out/'review.json'}\n\nNATIVE CHAT\nEarlier native Chat tool call and role answers remain in “BIWN — Local Roles and Firmware Checkpoint.” No new native Chat test or MCP process refresh verified this turn. Background SDK work follows the request to proceed when locked. Chat histories have not been injected or edited.\n{native}\n\nADVERTISING\nAnalysis Pilot v2 is trained, exported and loadable, but semantic/grammar/rubric/tool-format failures prevent promotion. Everyday base remains active.\n{ROOT/'verification/advertising-analysis-v2-review.json'}\n\nFuture 256GB profile remains unbenchmarked. The complete decompilation and full-game boot goal remain active.\n''')
    for name in ['START HERE.txt','CURRENT DECOMPILATION.txt','CURRENT LOCAL INFERENCE.txt']:shutil.copy2(ROOT/name,out/('current-'+name))
    path=ROOT/'verification/NEXT SOURCE AND INFERENCE WORK.json';n=json.loads(path.read_text());n.update(local_audit=str(out),local_roles_this_turn=result,last_turn_classification='progress',new_training_this_turn=False);save(path,n)
    feedback=ROOT/'training/feedback/firmware-initial-GPU-20261015.jsonl';feedback.write_text(json.dumps(dict(directory=str(local),status=result['status'],used_in_weight_training=False,independent_heldout_eval=False))+'\n')
    assert all(hashlib.sha256(Path(x['snapshot']).read_bytes()).hexdigest()==x['sha256']for x in review['manifest'])
    print(json.dumps(result))

if __name__=='__main__':main()
